export function ProductPictogram({ icon, category, className = "w-7 h-7 stroke-[1.75]" }) {
  const iconMap = {
    Apple, Carrot, Fish, Milk, Egg, Wheat, Wine, Flame, Package, Droplets,
    Heart, Shield, Tag, Coffee, Cookie, Cake, Sun, Moon, Layers, Sparkles, Utensils,
    ShoppingCart, Beef, Pizza, Salad, IceCream, UtensilsCrossed, Cherry, Citrus,
    Banana, Nut, Soup, Beer, GlassWater, Sandwich, Sparkle,
    Pill, Bath, Box, Scissors, Drumstick, Thermometer, Flower2, Leaf, ShieldAlert, Star
  };

  const categoryIconMap = {
    'Saisonales': Sparkles,
    'Obst': Apple,
    'Gemüse': Carrot,
    'Brot & Gebäck': Wheat,
    'Milchprodukte': Milk,
    'Käse': Layers,
    'Fleisch': Flame,
    'Fisch': Fish,
    'Grundzutaten': Egg,
    'Gewürze': Sparkles,
    'Fertig & Tiefkühlprodukte': Package,
    'Getreideprodukte': Wheat,
    'Süssigkeiten': Cookie,
    'Getränke': Wine,
    'Haushalt': Shield,
    'Pflege & Gesundheit': Heart,
  };

  const IconComp = iconMap[icon] || categoryIconMap[category] || ShoppingCart;
  return <IconComp className={className} />;
}

